{
  "findings": [
    {
      "ref": "R271",
      "area": "age_gating",
      "claim": "A parent reports that the app does not allow control over which holiday themes are shown, and they wish for parental controls to hide certain holiday content.",
      "stance": "risk",
      "quote": "I wish it was mindful on what families do and do not celebrate in terms of holidays. I hope that in the near future it allows parents the opportunity to control which holiday themes they want to expose their child to (or withhold) depending on the family’s preferences and values."
    },
    {
      "ref": "R283",
      "area": "content",
      "claim": "A parent reports that the app skips lessons when a child accidentally hits the home button, causing frustration as the lesson cannot be resumed.",
      "stance": "risk",
      "quote": "My kid is two and loves to play this but he will accidentally hit the home button in the middle of a lesson and then try to resume it but it completely skips to the next lesson. I wish there was a way to resume where he had left off because there is no way to track down the lesson he accidentally skipped and it’s frustrating."
    },
    {
      "ref": "R303",
      "area": "contact",
      "claim": "A parent reports that the app includes a voice prompt saying 'Ask a grown-up to check your Internet' that cannot be turned off, which may be concerning for children with autism.",
      "stance": "risk",
      "quote": "It would be nice if you could have an option, especially for users with autism where you can turn that voice prompt to check the Internet off and the pro could be something like a text Bubble or picture or something of that nature."
    },
    {
      "ref": "R328",
      "area": "age_gating",
      "claim": "A parent reports that the app is not suitable for young children, as a five-year-old could not use it and became frustrated, leading to a one-star rating.",
      "stance": "risk",
      "quote": "Kids can play this they have to have like ideas and stuff. Why would they know that my five-year-old son can’t even play it so I had to tell him his IDs and he could never get on this and once he got on it, he hated it. He didn’t even wanna play it. One star!"
    },
    {
      "ref": "R339",
      "area": "developer_record",
      "claim": "A reviewer calls the app 'Kun academy' and describes it as 'Best learning game ever', but this appears to be a misspelling or unrelated reference without supporting evidence of regulatory issues.",
      "stance": "neutral",
      "quote": "Best learning game ever"
    },
    {
      "ref": "R340",
      "area": "developer_record",
      "claim": "A reviewer labels the app 'F6vhufhcghuocfgfgc' and calls it 'Worst app ever', but this is nonsensical input with no verifiable claim about the developer's record.",
      "stance": "neutral",
      "quote": "Worst app ever"
    },
    {
      "ref": "R326",
      "area": "money",
      "claim": "A parent reports that the app is free and highly recommends it for homeschooling, emphasizing that there are no costs or hidden fees.",
      "stance": "mitigation",
      "quote": "I even like letting my kids play it in the car! Highly recommend! Best free learning game!"
    },
    {
      "ref": "R330",
      "area": "money",
      "claim": "A parent reports that the app was expected to be paid but is actually free, and they give it five stars after realizing it costs nothing.",
      "stance": "mitigation",
      "quote": "So I got this for me so I could learn better. When you first get it, you have to put it on your passcode so I have my dad do it. And I thought I had to pay for it though it just really looks like you have to pay for it but five stars from me."
    },
    {
      "ref": "R300",
      "area": "content",
      "claim": "A reviewer states the app is 'Bad' and claims it caused their child to become depressed, indicating negative content or experience.",
      "stance": "risk",
      "quote": "My child is now completely depressed because this app. This app is terrible and my child hates it please remove this app from App Store"
    },
    {
      "ref": "R332",
      "area": "content",
      "claim": "A grandparent reports that their grandchildren love the app and learn every day, indicating positive content engagement.",
      "stance": "neutral",
      "quote": "My grandchildren love this app! They learn every day."
    },
    {
      "ref": "R333",
      "area": "bug_report",
      "claim": "A reviewer reports that after tapping all friends to go outside for a 'surprise', the app returns to the main screen and loops endlessly without progressing.",
      "stance": "bug_report",
      "quote": "After tapping all the friends to go outside for the “surprise” it goes back to the main screen and doesn’t progress and has to do it over again in an endless loop."
    },
    {
      "ref": "R338",
      "area": "content",
      "claim": "A reviewer states that the app is 'The worst app' and claims it is boring for older children, suggesting inappropriate content for their age group.",
      "stance": "risk",
      "quote": "I don’t like it cause I’m nine and it’s very boring. I don’t even play with it so if you’re a grown-up out there, don’t get your kid if it’s 8, nine and 10 I don’t like it for sure."
    },
    {
